// F1 - SIMULAR DADOS DO PROCESSO

// Simula o comportamento de um processo de pré-aquecimento
// de água com estados operacionais.


// 1. Parâmetros do processo
const temperatura_minima_liberacao = 36; // 2*temperatura_ambiente
const temperatura_maxima_seguranca = 70; //Suposição
const temperatura_ambiente = 18; //Considerando Alto Vale do Itajaí
const vazao_nominal_l_min = 12; // litros/minutos
const tempo_maturacao_alvo = 20; //minutos


// 2. Recuperação do contexto
let estado_processo = context.get("estado_processo") || "RECARREGANDO";
let temperatura_entrada = context.get("temperatura_entrada") || temperatura_ambiente;
let temperatura_saida = context.get("temperatura_saida") || temperatura_ambiente + 2;
const ciclo = context.get("ciclo") || 1;

// A amostra descreve o estado atual. O contexto prepara a próxima execução.
let proximo_estado = estado_processo;
let proximo_ciclo = ciclo;
let nivel_tubulacao_percentual = context.get("nivel_tubulacao_percentual") || 0;
let tempo_maturacao_min = context.get("tempo_maturacao_min") || 0;


// 3. Simulação do fator solar
let data = new Date();
let hora = data.getHours();
let minuto = data.getMinutes();
let hora_decimal = hora + (minuto / 60);

// Simulação simples da incidência solar
let fator_solar = Math.max(0, Math.sin((hora_decimal - 6) * Math.PI / 12));

// 4. Variáveis de saída
let valvula_entrada = "Fechada";
let valvula_saida = "Fechada";
let vazao_l_min = 0;
let observacao = "";

// 5. Máquina de estados
switch (estado_processo) {

    case "AQUECENDO":
        valvula_entrada = "Fechada";
        valvula_saida = "Fechada";
        vazao_l_min = 0;

        let ganho_temperatura = (fator_solar * 1.5) - 0.05;

        temperatura_entrada += ganho_temperatura * 0.4;
        temperatura_saida += ganho_temperatura * 1.2;

        observacao = "Aquecendo a água na tubulação";

        if (temperatura_saida >= temperatura_minima_liberacao) {
            proximo_estado = "MATURANDO";
            tempo_maturacao_min = 0;
        }
        break;

    case "MATURANDO":
        valvula_entrada = "Fechada";
        valvula_saida = "Fechada";
        vazao_l_min = 0;

        tempo_maturacao_min += 1;
        temperatura_saida += fator_solar * 0.2;

        observacao = "Aguardando estabilização térmica";

        if (tempo_maturacao_min >= tempo_maturacao_alvo) {
            proximo_estado = "TRANSFERINDO";
        }
        break;

    case "TRANSFERINDO":
        valvula_entrada = "Aberta";
        valvula_saida = "Aberta";
        vazao_l_min = vazao_nominal_l_min + (Math.random() - 0.5);

        temperatura_entrada = (temperatura_entrada * 0.5) + (temperatura_ambiente * 0.5);
        temperatura_saida -= 1.5;

        observacao = "Transferindo água aquecida para o tanque";

        if (temperatura_saida < temperatura_minima_liberacao - 5) {
            proximo_estado = "RECARREGANDO";
            nivel_tubulacao_percentual = 80;
            proximo_ciclo += 1;
        }
        break;

    case "RECARREGANDO":
    default:
        estado_processo = "RECARREGANDO";
        proximo_estado = estado_processo;
        valvula_entrada = "Aberta";
        valvula_saida = "Fechada";
        vazao_l_min = vazao_nominal_l_min * 0.8;

        nivel_tubulacao_percentual += 20;

        temperatura_entrada = temperatura_ambiente + Math.random();
        temperatura_saida = (temperatura_saida * 0.6) + (temperatura_entrada * 0.4);

        observacao = "Recarregando tubulação com água nova";

        if (nivel_tubulacao_percentual >= 100) {
            nivel_tubulacao_percentual = 100;
            proximo_estado = "AQUECENDO";
        }
        break;
}

// 6. Travamento de limites físicos
if (temperatura_saida > temperatura_maxima_seguranca) {
    temperatura_saida = temperatura_maxima_seguranca;
}

if (temperatura_entrada < temperatura_ambiente - 2) {
    temperatura_entrada = temperatura_ambiente - 2;
}

if (temperatura_saida < temperatura_entrada) {
    temperatura_saida = temperatura_entrada;
}

if (nivel_tubulacao_percentual > 100) {
    nivel_tubulacao_percentual = 100;
}

// 7. Montagem do payload padronizado
msg.payload = {
    origem: "simulado",
    timestamp: data.toISOString(),
    estado_processo: estado_processo,
    ciclo: ciclo,

    temperatura_entrada: Number(temperatura_entrada.toFixed(2)),
    temperatura_saida: Number(temperatura_saida.toFixed(2)),
    vazao_l_min: Number(vazao_l_min.toFixed(2)),

    valvula_entrada: valvula_entrada,
    valvula_saida: valvula_saida,
    nivel_tubulacao_percentual: Number(nivel_tubulacao_percentual.toFixed(2)),
    tempo_maturacao_min: Number(tempo_maturacao_min.toFixed(0)),

    fator_solar: Number(fator_solar.toFixed(2)),
    observacao: observacao
};

// 8. Salvamento do contexto
context.set("estado_processo", proximo_estado);
context.set("temperatura_entrada", temperatura_entrada);
context.set("temperatura_saida", temperatura_saida);
context.set("ciclo", proximo_ciclo);
context.set("nivel_tubulacao_percentual", nivel_tubulacao_percentual);
context.set("tempo_maturacao_min", tempo_maturacao_min);

// 9. Status visual do nó
node.status({
    fill: "blue",
    shape: "dot",
    text: `${estado_processo} | ${msg.payload.temperatura_saida}°C`
});

return msg;

// F2 - LER CLP VIRTUAL SIEMENS

// Dados recebidos do nó responsável pela comunicação
// com o CLP virtual Siemens.

let clp = msg.payload || {};

msg.payload = {

    origem: "clp",
    timestamp: clp.timestamp || new Date().toISOString(),

    estado_processo: clp.estado_processo ?? null,
    ciclo: clp.ciclo ?? null,

    temperatura_entrada: clp.temperatura_entrada ?? null,
    temperatura_saida: clp.temperatura_saida ?? null,
    vazao_l_min: clp.vazao_l_min ?? null,

    valvula_entrada: clp.valvula_entrada ?? null,
    valvula_saida: clp.valvula_saida ?? null,

    nivel_tubulacao_percentual:
        clp.nivel_tubulacao_percentual ?? null,

    tempo_maturacao_min:
        clp.tempo_maturacao_min ?? null,

    fator_solar: clp.fator_solar ?? null,

    observacao:
        clp.observacao || "Dados recebidos do CLP virtual Siemens"
};

node.status({
    fill: "green",
    shape: "dot",
    text: "Dados recebidos do CLP"
});

return msg;

// F0 - SELECIONAR ORIGEM DOS DADOS

// "simulado" = Node-RED gera os dados
// "clp"      = dados vindos do CLP virtual Siemens

msg.origem = "simulado";

return msg;

// F4 - VALIDAR DADOS

// Objetivo:
// Verificar se os dados normalizados possuem valores válidos
// e se atendem às regras definidas para o processo.

let d = msg.payload || {};
let alertas = [];
let status_validacao = "OK";

// FUNÇÃO AUXILIAR

// Mantém a prioridade:
function atualizarStatus(novoStatus) {
    const prioridade = {
        OK: 0,
        ALERTA: 1,
        ERRO: 2,
    };

    if (prioridade[novoStatus] > prioridade[status_validacao]) {
        status_validacao = novoStatus;
    }
}

// 1. VERIFICAR NORMALIZAÇÃO
if (d.normalizado !== true) {
    alertas.push("Dados não passaram pela etapa de normalização");
    atualizarStatus("ERRO");
}

// 2. VERIFICAR CAMPOS OBRIGATÓRIOS
if (!d.origem || d.origem === "desconhecida") {
    alertas.push("Origem dos dados não informada");
    atualizarStatus("ERRO");
}

if (!d.timestamp || Number.isNaN(Date.parse(d.timestamp))) {
    alertas.push("Timestamp inválido");
    atualizarStatus("ERRO");
}

if (!d.estado_processo || d.estado_processo === "INDEFINIDO") {
    alertas.push("Estado do processo não informado");
    atualizarStatus("ERRO");
}

// 3. VERIFICAR CAMPOS NUMÉRICOS
if (!Number.isFinite(d.temperatura_entrada)) {
    alertas.push("Temperatura de entrada inválida");
    atualizarStatus("ERRO");
}

if (!Number.isFinite(d.temperatura_saida)) {
    alertas.push("Temperatura de saída inválida");
    atualizarStatus("ERRO");
}

if (!Number.isFinite(d.vazao_l_min)) {
    alertas.push("Vazão inválida");
    atualizarStatus("ERRO");
}

if (!Number.isFinite(d.nivel_tubulacao_percentual)) {
    alertas.push("Nível da tubulação inválido");
    atualizarStatus("ERRO");
}

if (!Number.isFinite(d.tempo_maturacao_min)) {
    alertas.push("Tempo de maturação inválido");
    atualizarStatus("ERRO");
}

if (!Number.isFinite(d.ciclo)) {
    alertas.push("Número do ciclo inválido");
    atualizarStatus("ERRO");
}

// Ciclo deve ser um número inteiro.
if (Number.isFinite(d.ciclo) && !Number.isInteger(d.ciclo)) {
    alertas.push("Número do ciclo deve ser inteiro");
    atualizarStatus("ERRO");
}

// 4. APLICAR LIMITES
if (Number.isFinite(d.temperatura_entrada) && (d.temperatura_entrada < 0 || d.temperatura_entrada > 100)) {
    alertas.push("Temperatura de entrada fora da faixa esperada");
    atualizarStatus("ALERTA");
}

if (Number.isFinite(d.temperatura_saida) && (d.temperatura_saida < 0 || d.temperatura_saida > 110)) {
    alertas.push("Temperatura de saída fora da faixa esperada");
    atualizarStatus("ALERTA");
}

if (Number.isFinite(d.vazao_l_min) && (d.vazao_l_min < 0 || d.vazao_l_min > 100)) {
    alertas.push("Vazão fora da faixa esperada");
    atualizarStatus("ALERTA");
}

if (Number.isFinite(d.nivel_tubulacao_percentual) && (d.nivel_tubulacao_percentual < 0 || d.nivel_tubulacao_percentual > 100)) {
    alertas.push("Nível da tubulação fora da faixa de 0% a 100%");
    atualizarStatus("ALERTA");
}

if (Number.isFinite(d.tempo_maturacao_min) && d.tempo_maturacao_min < 0) {
    alertas.push("Tempo de maturação negativo");
    atualizarStatus("ALERTA");
}

if (Number.isFinite(d.ciclo) && d.ciclo < 0) {
    alertas.push("Número do ciclo negativo");
    atualizarStatus("ALERTA");
}

// O fator solar é opcional.
// Quando informado, deve estar entre 0 e 1.

if (d.fator_solar !== null && (!Number.isFinite(d.fator_solar) || d.fator_solar < 0 || d.fator_solar > 1)) {
    alertas.push("Fator solar fora da faixa de 0 a 1");
    atualizarStatus("ALERTA");
}

// 5. VALIDAR ESTADOS OPERACIONAIS
const estados_validos = [
    "RECARREGANDO",
    "AQUECENDO",
    "MATURANDO",
    "TRANSFERINDO",
];

if (d.estado_processo && d.estado_processo !== "INDEFINIDO" && !estados_validos.includes(d.estado_processo)) {
    alertas.push("Estado do processo desconhecido");
    atualizarStatus("ALERTA");
}

// 6. VALIDAR ESTADO DAS VÁLVULAS
if (d.valvula_entrada === "Indefinida") {
    alertas.push("Estado da válvula de entrada indefinido");
    atualizarStatus("ALERTA");
}

if (d.valvula_saida === "Indefinida") {
    alertas.push("Estado da válvula de saída indefinido");
    atualizarStatus("ALERTA");
}

// 7. REGRAS DE CONSISTÊNCIA DO PROCESSO

// RECARREGANDO:
// entrada aberta e saída fechada.
if (d.estado_processo === "RECARREGANDO" && (d.valvula_entrada !== "Aberta" || d.valvula_saida !== "Fechada")) {
    alertas.push("Configuração das válvulas incompatível com o estado RECARREGANDO",);
    atualizarStatus("ALERTA");
}

// AQUECENDO:
// ambas as válvulas devem estar fechadas.
if (d.estado_processo === "AQUECENDO" && (d.valvula_entrada !== "Fechada" || d.valvula_saida !== "Fechada")) {
    alertas.push("Configuração das válvulas incompatível com o estado AQUECENDO");
    atualizarStatus("ALERTA");
}

// MATURANDO:
// ambas as válvulas devem estar fechadas.
if (d.estado_processo === "MATURANDO" && (d.valvula_entrada !== "Fechada" || d.valvula_saida !== "Fechada")) {
    alertas.push("Configuração das válvulas incompatível com o estado MATURANDO");
    atualizarStatus("ALERTA");
}

// TRANSFERINDO:
// ambas as válvulas devem estar abertas.
if (d.estado_processo === "TRANSFERINDO" && (d.valvula_entrada !== "Aberta" || d.valvula_saida !== "Aberta")) {
    alertas.push("Configuração das válvulas incompatível com o estado TRANSFERINDO",);
    atualizarStatus("ALERTA");
}

// Não deve existir fluxo durante AQUECENDO ou MATURANDO.
if (Number.isFinite(d.vazao_l_min) && (d.estado_processo === "AQUECENDO" || d.estado_processo === "MATURANDO") && d.vazao_l_min > 0.5) {
    alertas.push("Fluxo detectado em estado sem transferência");
    atualizarStatus("ALERTA");
}

// Durante TRANSFERINDO deve existir vazão.

if (Number.isFinite(d.vazao_l_min) && d.estado_processo === "TRANSFERINDO" && d.vazao_l_min <= 0.5) {
    alertas.push("Transferência sem vazão detectada");
    atualizarStatus("ALERTA");
}

// Verifica possível perda térmica.

if (Number.isFinite(d.temperatura_entrada) && Number.isFinite(d.temperatura_saida) && d.temperatura_saida < d.temperatura_entrada) {
    alertas.push("Temperatura de saída menor que temperatura de entrada");
    atualizarStatus("ALERTA");
}

// 8. MONTAGEM DO PAYLOAD VALIDADO
d.validado = status_validacao !== "ERRO";
d.status_validacao = status_validacao;
d.alertas = alertas;
msg.payload = d;

// 9. STATUS VISUAL DO NÓ
let cor = "green";

if (status_validacao === "ALERTA") {
    cor = "yellow";
}

if (status_validacao === "ERRO") {
    cor = "red";
}

node.status({
    fill: cor,
    shape: "dot",
    text: `${status_validacao} | ${alertas.length} alerta(s)`,
});

// 10. BLOQUEIO DE ERROS CRÍTICOS
if (status_validacao === "ERRO") {
    node.warn(alertas.join(" | "));

    return null;
}

return msg;

// F3 - NORMALIZAR ESTRUTURA

// Objetivo:
// Garantir que os dados vindos do simulador ou do CLP
// tenham sempre o mesmo formato para as próximas etapas.

let d = msg.payload || {};
let data = new Date();


// 1. FUNÇÕES AUXILIARES
// Valores ausentes, vazios ou inválidos são definidos como null.
function normalizarNumero(valor) {

    if (
        valor === null ||
        valor === undefined ||
        (typeof valor === "string" && valor.trim() === "")
    ) {
        return null;
    }

    let numero = Number(valor);

    if (!Number.isFinite(numero)) {
        return null;
    }

    return numero;
}


// Padroniza os valores das válvulas.
function normalizarValvula(valor) {

    valor = String(valor ?? "Indefinida")
        .trim()
        .toLowerCase();

    if (valor === "aberta") {
        return "Aberta";
    }

    if (valor === "fechada") {
        return "Fechada";
    }

    return "Indefinida";
}


// 2. NORMALIZAÇÃO DOS CAMPOS PRINCIPAIS
let origem = String(
    d.origem ||
    msg.origem ||
    "desconhecida"
)
    .trim()
    .toLowerCase();


let timestamp;

if (
    d.timestamp === null ||
    d.timestamp === undefined ||
    d.timestamp === ""
) {
    timestamp = data.toISOString();
} else {
    timestamp = String(d.timestamp).trim();
}


let estado_processo = String(
    d.estado_processo || "INDEFINIDO"
)
    .trim()
    .toUpperCase();


// 3. NORMALIZAÇÃO DOS CAMPOS NUMÉRICOS
let ciclo = normalizarNumero(d.ciclo);

let temperatura_entrada = normalizarNumero(d.temperatura_entrada);

let temperatura_saida = normalizarNumero(d.temperatura_saida);

let vazao_l_min = normalizarNumero(d.vazao_l_min);

let nivel_tubulacao_percentual = normalizarNumero(d.nivel_tubulacao_percentual);

let tempo_maturacao_min = normalizarNumero(d.tempo_maturacao_min);

let fator_solar = normalizarNumero(d.fator_solar);

// 4. NORMALIZAÇÃO DAS VÁLVULAS
let valvula_entrada = normalizarValvula(d.valvula_entrada);

let valvula_saida = normalizarValvula(d.valvula_saida);

// 5. NORMALIZAÇÃO DA OBSERVAÇÃO
let observacao = String(d.observacao || "").trim();


// 6. MONTAGEM DO PAYLOAD NORMALIZADO
msg.payload = {

    origem: origem,
    timestamp: timestamp,
    estado_processo: estado_processo,
    ciclo: ciclo,

    temperatura_entrada: temperatura_entrada,
    temperatura_saida: temperatura_saida,
    vazao_l_min: vazao_l_min,

    valvula_entrada: valvula_entrada,
    valvula_saida: valvula_saida,

    nivel_tubulacao_percentual:
        nivel_tubulacao_percentual,

    tempo_maturacao_min:
        tempo_maturacao_min,

    fator_solar: fator_solar,

    observacao: observacao,

    normalizado: true
};

// 7. STATUS VISUAL DO NÓ
node.status({
    fill: "blue",
    shape: "dot",
    text: `${origem} | ${estado_processo}`
});

return msg;

// F5 - CALCULAR INDICADORES

// Objetivo:
// Calcular os principais indicadores do processo:
// delta_t, volume, energia e economia.

let d = msg.payload || {};

// 1. Veficar validação do F4
if (d.validado !== true) {
    node.warn("Dados não passaram pela etapa de validação");
    return null;
}

// 2. Constantes do processo
const calor_especifico_agua_kj = 4.18;   // kJ/kg°C
const litros_para_kg = 1;                 // 1 litro de água ≈ 1 kg
const intervalo_min = 1;                  // intervalo do inject em minutos
const delta_t_referencia = 15;            // referência para desempenho térmico percentual
const tarifa_recebida = Number(msg.preco_kwh);

const preco_kwh = Number.isFinite(tarifa_recebida) && tarifa_recebida > 0
    ? tarifa_recebida
    : 0.52;

// 3. Recuperação dos dados recebidos
let temperatura_entrada = d.temperatura_entrada;
let temperatura_saida = d.temperatura_saida;
let vazao_l_min = d.vazao_l_min;

// 4. Cálculo do Delta T
let delta_t = temperatura_saida - temperatura_entrada;

// valores negativos são considerados zero.
if (delta_t < 0) {
    delta_t = 0;
}


// 5. Cálculo do volume do instante
let volume_instante_l = vazao_l_min * intervalo_min;

// Desconsidera volumes residuais muito pequenos
if (volume_instante_l < 0.05) {
    volume_instante_l = 0;
}


// 6. Controle de reset diário
let data = new Date();

//ANO-MES-DIA
let data_hoje =
    data.getFullYear() + "-" +
    String(data.getMonth() + 1).padStart(2, "0") + "-" +
    String(data.getDate()).padStart(2, "0");

let ultima_data = context.get("ultima_data") ?? data_hoje;
let volume_total_l = context.get("volume_total_l") ?? 0;
let energia_total_kwh = context.get("energia_total_kwh") ?? 0;

if (ultima_data !== data_hoje) {
    volume_total_l = 0;
    energia_total_kwh = 0;
}


// 7. Acúmulo do volume
volume_total_l += volume_instante_l;


//----------------------------------------------------
// 8. Cálculo da energia
// Fórmula: Q = m * c * ΔT
// m = massa da água em kg
// c = calor específico da água
// ΔT = diferença de temperatura
//----------------------------------------------------

let massa_kg = volume_instante_l * litros_para_kg;
let energia_kj = 0;

if (vazao_l_min > 0.5 && delta_t > 0) {
    energia_kj = massa_kg * calor_especifico_agua_kj * delta_t;
}

let energia_kwh = energia_kj / 3600;


// 9. Acúmulo da energia
energia_total_kwh += energia_kwh;


// 10. Indicador Percentual
let desempenho_termico_percentual = (delta_t / delta_t_referencia) * 100;

if (desempenho_termico_percentual > 100) {
    desempenho_termico_percentual = 100;
}

if (desempenho_termico_percentual < 0) {
    desempenho_termico_percentual = 0;
}

let economia_reais = energia_total_kwh * preco_kwh;


// 11. Atualização do payload
d.delta_t = Number(delta_t.toFixed(2));
d.volume_instante_l = Number(volume_instante_l.toFixed(3));
d.volume_total_l = Number(volume_total_l.toFixed(2));
d.energia_kj = Number(energia_kj.toFixed(2));
d.energia_kwh = Number(energia_kwh.toFixed(5));
d.energia_total_kwh = Number(energia_total_kwh.toFixed(5));
d.desempenho_termico_percentual = Number(desempenho_termico_percentual.toFixed(2));
d.economia_reais = Number(economia_reais.toFixed(2));
d.processado = true;

msg.payload = d;


// 12. Salvamento do contexto
context.set("ultima_data", data_hoje);
context.set("volume_total_l", volume_total_l);
context.set("energia_total_kwh", energia_total_kwh);


// 13. Status visual do nó
node.status({
    fill: "green",
    shape: "dot",
    text: `ΔT ${d.delta_t}°C | ${d.energia_total_kwh} kWh`
});

return msg;

// Tarifa de energia utilizada para estimativa financeira.
// Valor configurável diretamente no fluxo do Node-RED.
msg.preco_kwh = 0.51;

return msg;

// F6 - CLASSIFICAR PROCESSO

// Objetivo:
// Classificar o estado operacional do sistema com base
// nos dados processados na etapa anterior.

let d = msg.payload || {};

// 1. Verificar se os dados passaram pela classificação
if (d.processado !== true) {
    node.warn("Dados não passaram pela etapa de processamento");
    return null;
}

// Limitadores
const fluxo_minimo_l_min = 0.5;
const temp_baixa_limite = 35;
const temp_moderada_limite = 45;
const temp_adequada_limite = 60;
const temp_critica = 85;
const temp_minima_transferencia = 40;
const delta_t_baixo = 2;
const eficiencia_media = 30;
const eficiencia_alta = 70;

// 2. Recuperação dos dados principais
let estado = d.estado_processo;
let temperatura_saida = d.temperatura_saida;
let vazao_l_min = d.vazao_l_min;
let delta_t = d.delta_t;
let desempenho_termico_percentual = d.desempenho_termico_percentual;
let valvula_entrada = d.valvula_entrada;
let valvula_saida = d.valvula_saida;

// 3. Status operacional
let status_operacional = "Indefinido";

switch (estado) {
    case "RECARREGANDO":
        status_operacional = "Recarregando";
        break;

    case "AQUECENDO":
        status_operacional = "Aquecendo";
        break;

    case "MATURANDO":
        status_operacional = "Maturando";
        break;

    case "TRANSFERINDO":
        status_operacional = "Transferindo";
        break;

    default:
        status_operacional = "Indefinido";
        break;
}

// 4. Condição térmica
let condicao_termica = "Indefinida";

if (temperatura_saida < temp_baixa_limite) {
    condicao_termica = "Baixa";
}

else if (temperatura_saida < temp_moderada_limite) {
    condicao_termica = "Moderada";
}

else if (temperatura_saida <= temp_adequada_limite) {
    condicao_termica = "Adequada";
}

else {
    condicao_termica = "Elevada";
}

// 5. Condição de transferência
let condicao_transferencia = "Sem fluxo";

if (vazao_l_min > fluxo_minimo_l_min) {
    if (valvula_entrada === "Aberta" && valvula_saida === "Aberta") {
        condicao_transferencia = "Transferindo água";
    }
    else if (valvula_entrada === "Aberta" && valvula_saida === "Fechada") {
        condicao_transferencia = "Recarregando tubulação";
    }
    else {
        condicao_transferencia = "Fluxo em condição incomum";
    }
}

// 6. Faixa de eficiência
let faixa_desempenho_termico = "Baixa";

if (desempenho_termico_percentual >= eficiencia_media && desempenho_termico_percentual < eficiencia_alta) {
    faixa_desempenho_termico = "Média";
}

else if (desempenho_termico_percentual >= eficiencia_alta) {
    faixa_desempenho_termico = "Alta";
}

// 7. Status das válvulas
let status_valvulas = "Indefinido";

if (valvula_entrada === "Fechada" && valvula_saida === "Fechada") {
    status_valvulas = "Ambas fechadas";
}

else if (valvula_entrada === "Aberta" && valvula_saida === "Aberta") {
    status_valvulas = "Ambas abertas";
}

else if (valvula_entrada === "Aberta" && valvula_saida === "Fechada") {
    status_valvulas = "Entrada aberta";
}

else if (valvula_entrada === "Fechada" && valvula_saida === "Aberta") {
    status_valvulas = "Configuração anômala";
}

// 8. Criticidade operacional
let criticidade = "Normal";

if (temperatura_saida > temp_critica) {
    criticidade = "Crítica - Alta temperatura";
}

else if ((estado === "TRANSFERINDO" || estado === "RECARREGANDO") && vazao_l_min <= fluxo_minimo_l_min) {
    criticidade = "Crítica - Falha de fluxo";
}

else if (estado === "TRANSFERINDO" && temperatura_saida < temp_minima_transferencia) {
    criticidade = "Atenção - Perda de calor";
}

else if (delta_t < delta_t_baixo && (estado === "AQUECENDO" || estado === "MATURANDO")) {
    criticidade = "Atenção - Baixo ganho térmico";
}

// 9. Atualização do payload
d.status_operacional = status_operacional;
d.condicao_termica = condicao_termica;
d.condicao_transferencia = condicao_transferencia;
d.faixa_desempenho_termico = faixa_desempenho_termico;
d.status_valvulas = status_valvulas;
d.criticidade = criticidade;
d.classificado = true;

msg.payload = d;

// 10. Status visual do nó
let cor = "green";

if (criticidade.startsWith("Atenção")) {
    cor = "yellow";
}

if (criticidade.startsWith("Crítica")) {
    cor = "red";
}

node.status({
    fill: cor,
    shape: "dot",
    text: `${status_operacional} | ${criticidade}`
});

return msg;

